-- Schema-only snapshot of connected Rehla public tables, 18 October 2026.
-- No business records or credentials are included.
CREATE SEQUENCE public.orders_order_number_seq;
CREATE TABLE public.clients (id uuid DEFAULT uuid_generate_v4() NOT NULL, company_name text NOT NULL, contact_person text NOT NULL, phone text DEFAULT ''::text, email text DEFAULT ''::text, address text DEFAULT ''::text, tax_number text DEFAULT ''::text, created_at timestamp with time zone DEFAULT now(), fulfillment_fee_percentage numeric(5,2) DEFAULT 0, storage_fee_monthly numeric(10,2) DEFAULT 0, storage_fee_per_unit numeric(10,2) DEFAULT 0);
CREATE TABLE public.customers (id uuid DEFAULT gen_random_uuid() NOT NULL, shopify_customer_id text, email text, first_name text, last_name text, phone text, address text, city text, province text, country text DEFAULT 'Egypt'::text, orders_count integer DEFAULT 0, total_spent numeric DEFAULT 0, tags text, note text, verified_email boolean DEFAULT false, accepts_marketing boolean DEFAULT false, shopify_state text, shopify_created_at timestamp with time zone, last_synced_at timestamp with time zone DEFAULT now(), created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.delivery_log (id uuid DEFAULT uuid_generate_v4() NOT NULL, delivery_order_id uuid NOT NULL, event text NOT NULL, notes text DEFAULT ''::text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.delivery_orders (id uuid DEFAULT uuid_generate_v4() NOT NULL, order_id uuid NOT NULL, driver_id uuid, delivery_type text DEFAULT 'own_driver'::text NOT NULL, status text DEFAULT 'pending'::text NOT NULL, customer_address text DEFAULT ''::text NOT NULL, cod_amount numeric(10,2) DEFAULT 0, failed_reason text, tracking_number text, bosta_shipment_id text, notes text DEFAULT ''::text, assigned_at timestamp with time zone, delivered_at timestamp with time zone, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), cod_collected boolean DEFAULT false NOT NULL);
CREATE TABLE public.drivers (id uuid DEFAULT uuid_generate_v4() NOT NULL, user_id uuid, name text NOT NULL, phone text NOT NULL, zone text DEFAULT ''::text, status text DEFAULT 'active'::text NOT NULL, uuid_link uuid DEFAULT uuid_generate_v4(), created_at timestamp with time zone DEFAULT now(), availability_status text DEFAULT 'available'::text NOT NULL);
CREATE TABLE public.expenses (id uuid DEFAULT uuid_generate_v4() NOT NULL, title text NOT NULL, description text DEFAULT ''::text, category text NOT NULL, amount numeric(10,2) NOT NULL, status text DEFAULT 'pending'::text NOT NULL, date date NOT NULL, approved_by text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.inventory_log (id uuid DEFAULT uuid_generate_v4() NOT NULL, product_id uuid, sku text NOT NULL, event_type text NOT NULL, quantity_changed integer NOT NULL, previous_quantity integer DEFAULT 0, new_quantity integer DEFAULT 0, notes text DEFAULT ''::text, handler_id uuid, handler_name text DEFAULT ''::text, warehouse_id uuid, created_at timestamp with time zone DEFAULT now(), order_id uuid, order_number text);
CREATE TABLE public.invoice_items (id uuid DEFAULT uuid_generate_v4() NOT NULL, invoice_id uuid NOT NULL, description text NOT NULL, quantity integer DEFAULT 1 NOT NULL, unit_price numeric(10,2) NOT NULL, subtotal numeric(10,2) NOT NULL);
CREATE TABLE public.invoices (id uuid DEFAULT uuid_generate_v4() NOT NULL, client_id uuid, order_id uuid, invoice_number text NOT NULL, customer_name text NOT NULL, customer_email text DEFAULT ''::text, issue_date date DEFAULT CURRENT_DATE NOT NULL, due_date date DEFAULT (CURRENT_DATE + '14 days'::interval) NOT NULL, subtotal numeric(10,2) DEFAULT 0 NOT NULL, total numeric(10,2) DEFAULT 0 NOT NULL, notes text DEFAULT ''::text, status text DEFAULT 'Draft'::text NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.order_items (id uuid DEFAULT uuid_generate_v4() NOT NULL, order_id uuid NOT NULL, product_id uuid, sku text NOT NULL, name text NOT NULL, quantity integer NOT NULL, price numeric(10,2) NOT NULL, cost_per_unit numeric(10,2) DEFAULT 0, variant_id uuid);
CREATE TABLE public.orders (id uuid DEFAULT uuid_generate_v4() NOT NULL, order_number integer DEFAULT nextval('orders_order_number_seq'::regclass) NOT NULL, shopify_order_id text, customer_name text NOT NULL, customer_phone text DEFAULT 'N/A'::text NOT NULL, customer_email text DEFAULT ''::text, items jsonb DEFAULT '[]'::jsonb, subtotal numeric(10,2) DEFAULT 0 NOT NULL, total numeric(10,2) DEFAULT 0 NOT NULL, status text DEFAULT 'pending'::text NOT NULL, payment_status text DEFAULT 'pending'::text NOT NULL, payment_method text DEFAULT 'cash'::text, source text DEFAULT 'shopify'::text, created_at timestamp with time zone DEFAULT now(), shopify_order_name text, discount_amount numeric(10,2) DEFAULT 0 NOT NULL, discount_reason text DEFAULT ''::text, shopify_customer_id text, total_refunded numeric(10,2) DEFAULT 0);
CREATE TABLE public.payments (id uuid DEFAULT uuid_generate_v4() NOT NULL, invoice_id uuid NOT NULL, amount numeric(10,2) NOT NULL, payment_method text NOT NULL, paid_at timestamp with time zone DEFAULT now());
CREATE TABLE public.product_variants (id uuid DEFAULT uuid_generate_v4() NOT NULL, product_id uuid NOT NULL, sku text NOT NULL, size text DEFAULT ''::text, color text DEFAULT ''::text, stock_quantity integer DEFAULT 0 NOT NULL, price numeric(10,2), barcode text, shopify_variant_id text, created_at timestamp with time zone DEFAULT now(), variant_name text, cost_per_unit numeric DEFAULT 0, shopify_inventory_item_id text, image_url text, last_synced_at timestamp with time zone);
CREATE TABLE public.products (id uuid DEFAULT uuid_generate_v4() NOT NULL, sku text, name text NOT NULL, description text DEFAULT ''::text, barcode text, price numeric(10,2) NOT NULL, cost_per_unit numeric(10,2) DEFAULT 0, stock_quantity integer DEFAULT 0 NOT NULL, category text DEFAULT 'Uncategorized'::text NOT NULL, image_url text DEFAULT ''::text, brand text DEFAULT 'REHLA'::text NOT NULL, warehouse_id uuid, shopify_variant_id text, last_synced_at timestamp with time zone, created_at timestamp with time zone DEFAULT now(), client_id uuid, shopify_inventory_item_id text, shopify_product_id text);
CREATE TABLE public.returns (id uuid DEFAULT uuid_generate_v4() NOT NULL, order_id uuid, customer_name text DEFAULT ''::text NOT NULL, items jsonb DEFAULT '[]'::jsonb NOT NULL, reason text NOT NULL, status text DEFAULT 'pending'::text NOT NULL, notes text DEFAULT ''::text, handler_name text DEFAULT ''::text, restocked boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.shopify_refunds (id uuid DEFAULT gen_random_uuid() NOT NULL, shopify_refund_id text NOT NULL, shopify_order_id text NOT NULL, order_id uuid, order_name text, processed_at timestamp with time zone NOT NULL, amount numeric(10,2) DEFAULT 0 NOT NULL, reason text, note text, synced_at timestamp with time zone DEFAULT now());
CREATE TABLE public.sync_log (id uuid DEFAULT uuid_generate_v4() NOT NULL, synced_at timestamp with time zone DEFAULT now(), products_updated integer DEFAULT 0, products_skipped integer DEFAULT 0, products_created integer DEFAULT 0, orders_synced integer DEFAULT 0, triggered_by text NOT NULL, status text DEFAULT 'success'::text, error_details text DEFAULT ''::text, duration_ms integer DEFAULT 0, customers_synced integer DEFAULT 0);
CREATE TABLE public.user_profiles (id uuid NOT NULL, staff_id text NOT NULL, name text NOT NULL, email text NOT NULL, role text NOT NULL, phone text, avatar_url text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.warehouses (id uuid DEFAULT uuid_generate_v4() NOT NULL, code text NOT NULL, name text NOT NULL, location text NOT NULL, created_at timestamp with time zone DEFAULT now());
